set-variable.value:
@{
          return new JObject(
            new JProperty("input_tokens", null),
            new JProperty("cached_tokens", null),
            new JProperty("output_tokens", null),
            new JProperty("estimated", true),
            new JProperty("ingest_error", "failed_request_has_no_usage")
          );
        }

@{
          long consumed = 0;
          if (context.Variables.ContainsKey("tokensConsumed"))
          {
            consumed = Convert.ToInt64(context.Variables["tokensConsumed"]);
          }
          return new JObject(
            new JProperty("input_tokens", null),
            new JProperty("cached_tokens", null),
            new JProperty("output_tokens", null),
            new JProperty("tokens_consumed", consumed > 0 ? (JToken)new JValue(consumed) : JValue.CreateNull()),
            new JProperty("estimated", true),
            new JProperty("ingest_error", "stream_usage_breakdown_unavailable")
          );
        }

@{
              try {
                var body = context.Response.Body.As<JObject>(preserveContent: true);
                var usage = body["usage"] as JObject;
                var incoming = usage?["input_tokens_details"] as JObject;
                var outgoing = usage?["output_tokens_details"] as JObject;
                var counters = new[] { usage?["input_tokens"], usage?["output_tokens"],
                  usage?["total_tokens"], incoming?["text_tokens"], incoming?["image_tokens"],
                  outgoing?["text_tokens"], outgoing?["image_tokens"] };
                if (counters.Any(token => token == null || token.Type != JTokenType.Integer
                  || (long)token < 0)) { throw new Exception(); }
                long input = (long)usage["input_tokens"];
                long output = (long)usage["output_tokens"];
                var cachedValue = incoming?["cached_tokens"];
                if (cachedValue != null && (cachedValue.Type != JTokenType.Integer
                  || (long)cachedValue < 0 || (long)cachedValue > input)) { throw new Exception(); }
                long cached = cachedValue == null ? 0L : (long)cachedValue;
                if ((long)incoming["image_tokens"] != 0 || (long)outgoing["text_tokens"] != 0
                  || (long)incoming["text_tokens"] != input || (long)outgoing["image_tokens"] != output
                  || (long)usage["total_tokens"] != input + output) { throw new Exception(); }
                return new JObject(new JProperty("input_tokens", input - cached),
                  new JProperty("cached_tokens", cached), new JProperty("cache_write_tokens", 0),
                  new JProperty("output_tokens", output), new JProperty("estimated", false),
                  new JProperty("ingest_error", null));
              } catch {
                return new JObject(new JProperty("input_tokens", null),
                  new JProperty("cached_tokens", null), new JProperty("cache_write_tokens", null),
                  new JProperty("output_tokens", null), new JProperty("estimated", true),
                  new JProperty("ingest_error", "usage_parse_failed"));
              }
            }

@{
      try
      {
        var body = context.Response.Body.As<JObject>(preserveContent: true);
        var usage = body["usage"] as JObject;
        var output = usage?["completion_tokens"] ?? usage?["output_tokens"];
        // Cache writes bill well above cache reads (1.25x versus 0.1x of base input for
        // Anthropic), so the two are reported separately. cached_tokens stays the full bucket
        // and cache_write_tokens is its write-only subset.
        var cacheRead = (long?)usage?["prompt_tokens_details"]?["cached_tokens"]
          ?? (long?)usage?["input_tokens_details"]?["cached_tokens"]
          ?? (long?)usage?["cache_read_input_tokens"]
          ?? (long?)usage?["cached_tokens"] ?? 0;
        var cacheWrite = (long?)usage?["prompt_tokens_details"]?["cache_write_tokens"]
          ?? (long?)usage?["cache_creation_input_tokens"] ?? 0;
        // OpenAI reports prompt_tokens INCLUDING its cached subset, while Anthropic's
        // input_tokens EXCLUDES it. Both are normalized to the exclusive form so that
        // input + cached + output never counts the cached portion twice, and so that the
        // cached share is never billed at the full input rate as well as the cached rate.
        var promptTokens = (long?)usage?["prompt_tokens"];
        var inclusiveInput = promptTokens ?? ((bool)context.Variables["isResponsesOperation"]
          ? (long?)usage?["input_tokens"]
          : null);
        var input = inclusiveInput.HasValue
          ? (JToken)new JValue(Math.Max(inclusiveInput.Value - cacheRead - cacheWrite, 0))
          : usage?["input_tokens"];
        return new JObject(
          new JProperty("input_tokens", input),
          new JProperty("cached_tokens", new JValue(cacheRead + cacheWrite)),
          new JProperty("cache_write_tokens", new JValue(cacheWrite)),
          new JProperty("output_tokens", output),
          new JProperty("estimated", input == null || output == null),
          new JProperty("ingest_error", input == null || output == null ? "usage_missing" : null)
        );
      }
      catch
      {
        return new JObject(
          new JProperty("input_tokens", null),
          new JProperty("cached_tokens", null),
          new JProperty("cache_write_tokens", null),
          new JProperty("output_tokens", null),
          new JProperty("estimated", true),
          new JProperty("ingest_error", "usage_parse_failed")
        );
      }
        }
